// @ts-nocheck
const http = require('node:http');

const PORT = Number(process.env.PORT || 8080);
const UPSTREAM_URL = process.env.UPSTREAM_URL || 'http://127.0.0.1:8081';
const UPSTREAM_API_KEY = process.env.UPSTREAM_API_KEY || 'local-dev-key';

const SECTORS = new Set(['energy', 'mining', 'water', 'transport', 'oil_and_gas', 'ict']);
const STAGES = new Set(['idea', 'feasibility', 'tender', 'financing', 'construction', 'operation', 'cancelled']);
const COMPANY_ROLES = new Set(['owner', 'developer', 'epc_contractor', 'financier', 'consultant']);

function jsonResponse(res, status, body) {
  const data = Buffer.from(JSON.stringify(body));
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': data.length,
  });
  res.end(data);
}

function notFound(res) {
  jsonResponse(res, 404, { code: 'project_not_found' });
}

function upstreamUnavailable(res) {
  jsonResponse(res, 502, { code: 'upstream_unavailable' });
}

function parseDateIso(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const d = new Date(value + 'T00:00:00.000Z');
  if (Number.isNaN(d.getTime())) return null;
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}` === value ? value : null;
}

function validateKeyDate(obj) {
  return obj && typeof obj === 'object' && !Array.isArray(obj) &&
    typeof obj.label === 'string' && obj.label.trim().length > 0 &&
    typeof obj.date === 'string' && parseDateIso(obj.date);
}

function validateEditableFields(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  const keys = Object.keys(obj);
  const req = ['name', 'sector', 'country', 'stage', 'key_dates'];
  if (keys.length !== 5 || !req.every((k) => keys.includes(k))) return false;
  if (typeof obj.name !== 'string' || !obj.name.trim()) return false;
  if (typeof obj.country !== 'string' || !obj.country.trim()) return false;
  if (!SECTORS.has(obj.sector)) return false;
  if (!STAGES.has(obj.stage)) return false;
  if (!Array.isArray(obj.key_dates) || !obj.key_dates.every(validateKeyDate)) return false;
  return true;
}

function validateSaveRequest(obj) {
  return obj && typeof obj === 'object' && !Array.isArray(obj) &&
    Object.keys(obj).length === 2 &&
    validateEditableFields(obj.base) &&
    validateEditableFields(obj.proposed);
}

function detailFromStored(project) {
  return {
    id: project.id,
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
    key_dates: project.key_dates,
  };
}

function summaryFromStored(project) {
  return {
    id: project.id,
    name: project.name,
    sector: project.sector,
    country: project.country,
    stage: project.stage,
  };
}

function choose(base, proposed, current) {
  if (JSON.stringify(proposed) === JSON.stringify(base)) return { value: current, conflict: false };
  if (JSON.stringify(current) !== JSON.stringify(base) && JSON.stringify(current) !== JSON.stringify(proposed)) {
    return { value: current, conflict: true };
  }
  return { value: proposed, conflict: false };
}

function mergeEdit(base, proposed, current) {
  const n = choose(base.name, proposed.name, current.name);
  const s = choose(base.sector, proposed.sector, current.sector);
  const c = choose(base.country, proposed.country, current.country);
  const st = choose(base.stage, proposed.stage, current.stage);
  const kd = choose(base.key_dates, proposed.key_dates, current.key_dates);
  const merged = {
    name: n.value,
    sector: s.value,
    country: c.value,
    stage: st.value,
    key_dates: kd.value,
  };
  const conflicts = [];
  if (n.conflict) conflicts.push('name');
  if (s.conflict) conflicts.push('sector');
  if (c.conflict) conflicts.push('country');
  if (st.conflict) conflicts.push('stage');
  if (kd.conflict) conflicts.push('key_dates');
  return { merged, conflicts, changed: JSON.stringify(merged) !== JSON.stringify(current) };
}

async function upstreamFetch(path, options) {
  return fetch(new URL(path, UPSTREAM_URL), {
    ...options,
    headers: {
      'X-Api-Key': UPSTREAM_API_KEY,
      ...(options && options.headers ? options.headers : {}),
    },
  });
}

async function listProjects() {
  try {
    const r = await upstreamFetch('/projects');
    if (!r.ok) throw new Error('bad');
    const data = await r.json();
    if (!Array.isArray(data)) throw new Error('bad');
    return data.map(summaryFromStored);
  } catch {
    throw { kind: 'upstream' };
  }
}

async function getProject(id) {
  try {
    const r = await upstreamFetch(`/projects/${encodeURIComponent(id)}`);
    if (r.status === 404) throw { kind: 'notfound' };
    if (!r.ok) throw new Error('bad');
    const data = await r.json();
    return detailFromStored(data);
  } catch (e) {
    if (e && e.kind === 'notfound') throw e;
    throw { kind: 'upstream' };
  }
}

async function putProject(id, fields, linkedCompanies) {
  const body = { ...fields, linked_companies: linkedCompanies };
  const r = await upstreamFetch(`/projects/${encodeURIComponent(id)}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (r.status === 404) throw { kind: 'notfound' };
  if (!r.ok) throw { kind: 'uncertain' };
  const data = await r.json();
  return detailFromStored(data);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let buf = '';
    req.setEncoding('utf8');
    req.on('data', (c) => { buf += c; });
    req.on('end', () => {
      if (!buf) return resolve(null);
      try { resolve(JSON.parse(buf)); } catch { reject(new Error('invalid json')); }
    });
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const method = req.method || 'GET';

  if (method === 'GET' && url.pathname === '/api/projects') {
    try {
      const projects = await listProjects();
      return jsonResponse(res, 200, { projects });
    } catch {
      return upstreamUnavailable(res);
    }
  }

  const m = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  if (m && method === 'GET') {
    try {
      const project = await getProject(decodeURIComponent(m[1]));
      return jsonResponse(res, 200, { project });
    } catch (e) {
      if (e && e.kind === 'notfound') return notFound(res);
      return upstreamUnavailable(res);
    }
  }

  if (m && method === 'PUT') {
    let body;
    try {
      body = await readBody(req);
    } catch {
      return jsonResponse(res, 422, { detail: 'Invalid JSON' });
    }
    if (!validateSaveRequest(body)) return jsonResponse(res, 422, { detail: 'Validation error' });
    const id = decodeURIComponent(m[1]);

    let current;
    try {
      current = await getProject(id);
    } catch (e) {
      if (e && e.kind === 'notfound') return notFound(res);
      return upstreamUnavailable(res);
    }

    const merge = mergeEdit(body.base, body.proposed, current);
    if (merge.conflicts.length) {
      return jsonResponse(res, 409, {
        code: 'edit_conflict',
        current,
        conflicting_fields: merge.conflicts,
      });
    }
    if (!merge.changed) return jsonResponse(res, 200, { project: current });

    try {
      const saved = await putProject(id, merge.merged, current.linked_companies || []);
      return jsonResponse(res, 200, { project: saved });
    } catch (e) {
      if (e && e.kind === 'notfound') return notFound(res);
      if (e && e.kind === 'uncertain') {
        let observed = null;
        try {
          observed = await getProject(id);
        } catch {}
        return jsonResponse(res, 504, { code: 'write_uncertain', observed });
      }
      return upstreamUnavailable(res);
    }
  }

  res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify({ code: 'not_found' }));
});

server.listen(PORT, '0.0.0.0');

// @ts-nocheck
const http = require('node:http');

const PORT = Number(process.env.PORT || 8080);
const UPSTREAM_URL = process.env.UPSTREAM_URL || 'http://127.0.0.1:8081';
const UPSTREAM_API_KEY = process.env.UPSTREAM_API_KEY || 'local-dev-key';

function send(res, status, body) {
  const json = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(json),
  });
  res.end(json);
}

function notFound(res) {
  send(res, 404, { code: 'project_not_found' });
}

function unavailable(res) {
  send(res, 502, { code: 'upstream_unavailable' });
}

function uncertain(res, observed) {
  send(res, 504, { code: 'write_uncertain', observed });
}

function isPlainObject(v) {
  return !!v && typeof v === 'object' && !Array.isArray(v);
}

function validateIsoDate(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = new Date(s + 'T00:00:00Z');
  if (Number.isNaN(d.getTime())) return false;
  return d.toISOString().slice(0, 10) === s;
}

function parseKeyDate(v) {
  if (!isPlainObject(v)) return null;
  const keys = Object.keys(v);
  if (keys.length !== 2 || !('label' in v) || !('date' in v)) return null;
  if (typeof v.label !== 'string' || !v.label.trim()) return null;
  if (!validateIsoDate(v.date)) return null;
  return { label: v.label, date: v.date };
}

function parseEditableFields(v) {
  if (!isPlainObject(v)) return null;
  const keys = Object.keys(v);
  const required = ['name', 'sector', 'country', 'stage', 'key_dates'];
  if (keys.length !== 5 || !required.every((k) => k in v)) return null;
  if (typeof v.name !== 'string' || !v.name.trim()) return null;
  if (typeof v.country !== 'string' || !v.country.trim()) return null;
  if (typeof v.sector !== 'string' || typeof v.stage !== 'string') return null;
  if (!Array.isArray(v.key_dates)) return null;
  const key_dates = [];
  for (const item of v.key_dates) {
    const kd = parseKeyDate(item);
    if (!kd) return null;
    key_dates.push(kd);
  }
  return {
    name: v.name,
    sector: v.sector,
    country: v.country,
    stage: v.stage,
    key_dates,
  };
}

function parseProjectDetail(v) {
  if (!isPlainObject(v)) return null;
  if (typeof v.id !== 'string') return null;
  const editable = parseEditableFields(v);
  if (!editable) return null;
  return { id: v.id, ...editable };
}

function parseProjectSummary(v) {
  if (!isPlainObject(v)) return null;
  const keys = Object.keys(v);
  const required = ['id', 'name', 'sector', 'country', 'stage'];
  if (keys.length !== 5 || !required.every((k) => k in v)) return null;
  if (
    typeof v.id !== 'string' ||
    typeof v.name !== 'string' ||
    !v.name.trim() ||
    typeof v.country !== 'string' ||
    !v.country.trim() ||
    typeof v.sector !== 'string' ||
    typeof v.stage !== 'string'
  ) return null;
  return { id: v.id, name: v.name, sector: v.sector, country: v.country, stage: v.stage };
}

function parseStoredProject(v) {
  if (!isPlainObject(v)) return null;
  if (typeof v.id !== 'string') return null;
  const editable = parseEditableFields(v);
  if (!editable) return null;
  const linked = Array.isArray(v.linked_companies) ? v.linked_companies : [];
  return { id: v.id, ...editable, linked_companies: linked, raw: v };
}

function conflictFields(base, proposed, current) {
  const fields = ['name', 'sector', 'country', 'stage', 'key_dates'];
  const conflicts = [];
  const merged = {};
  for (const f of fields) {
    if (JSON.stringify(proposed[f]) === JSON.stringify(base[f])) {
      merged[f] = current[f];
    } else if (JSON.stringify(current[f]) === JSON.stringify(base[f])) {
      merged[f] = proposed[f];
    } else if (JSON.stringify(current[f]) === JSON.stringify(proposed[f])) {
      merged[f] = current[f];
    } else {
      merged[f] = current[f];
      conflicts.push(f);
    }
  }
  return {
    merged: {
      name: merged.name,
      sector: merged.sector,
      country: merged.country,
      stage: merged.stage,
      key_dates: merged.key_dates,
    },
    conflicts,
    changed: JSON.stringify(merged) !== JSON.stringify(current),
  };
}

async function readJson(req) {
  return await new Promise((resolve, reject) => {
    let data = '';
    req.setEncoding('utf8');
    req.on('data', (c) => (data += c));
    req.on('end', () => {
      if (!data) return resolve(null);
      try {
        resolve(JSON.parse(data));
      } catch {
        reject(new Error('bad json'));
      }
    });
    req.on('error', reject);
  });
}

async function upstreamFetch(path, options = {}) {
  const headers = Object.assign({}, options.headers || {}, { 'X-Api-Key': UPSTREAM_API_KEY });
  const res = await fetch(new URL(path, UPSTREAM_URL), { ...options, headers });
  let json = null;
  try {
    json = await res.json();
  } catch {
    json = null;
  }
  return { res, json };
}

async function getStoredProject(id) {
  const { res, json } = await upstreamFetch(`/projects/${encodeURIComponent(id)}`);
  if (res.status === 404) return { kind: 'not_found' };
  if (!res.ok) return { kind: 'unavailable' };
  const parsed = parseStoredProject(json);
  if (!parsed) return { kind: 'unavailable' };
  return { kind: 'ok', project: parsed };
}

async function listHandler(res) {
  const { res: upstreamRes, json } = await upstreamFetch('/projects');
  if (!upstreamRes.ok || !Array.isArray(json)) return unavailable(res);
  const projects = [];
  for (const item of json) {
    const p = parseStoredProject(item);
    if (!p) return unavailable(res);
    const summary = parseProjectSummary(p);
    if (!summary) return unavailable(res);
    projects.push(summary);
  }
  send(res, 200, { projects });
}

async function showHandler(res, id) {
  const got = await getStoredProject(id);
  if (got.kind === 'not_found') return notFound(res);
  if (got.kind !== 'ok') return unavailable(res);
  send(res, 200, { project: { id: got.project.id, name: got.project.name, sector: got.project.sector, country: got.project.country, stage: got.project.stage, key_dates: got.project.key_dates } });
}

async function saveHandler(req, res, id) {
  let body;
  try {
    body = await readJson(req);
  } catch {
    return send(res, 422, { detail: 'Invalid JSON' });
  }
  if (!isPlainObject(body) || Object.keys(body).length !== 2 || !('base' in body) || !('proposed' in body)) {
    return send(res, 422, { detail: 'Validation error' });
  }
  const base = parseEditableFields(body.base);
  const proposed = parseEditableFields(body.proposed);
  if (!base || !proposed) return send(res, 422, { detail: 'Validation error' });

  const got = await getStoredProject(id);
  if (got.kind === 'not_found') return notFound(res);
  if (got.kind !== 'ok') return unavailable(res);

  const current = {
    name: got.project.name,
    sector: got.project.sector,
    country: got.project.country,
    stage: got.project.stage,
    key_dates: got.project.key_dates,
  };
  const merge = conflictFields(base, proposed, current);
  if (merge.conflicts.length) {
    return send(res, 409, { code: 'edit_conflict', current: { id: got.project.id, ...current }, conflicting_fields: merge.conflicts });
  }
  if (JSON.stringify(merge.merged) === JSON.stringify(current)) {
    return send(res, 200, { project: { id: got.project.id, ...current } });
  }

  const upstreamBody = {
    ...merge.merged,
    linked_companies: got.project.linked_companies || [],
  };

  let putRes;
  let putJson = null;
  try {
    const r = await fetch(new URL(`/projects/${encodeURIComponent(id)}`, UPSTREAM_URL), {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        'X-Api-Key': UPSTREAM_API_KEY,
      },
      body: JSON.stringify(upstreamBody),
    });
    putRes = r;
    try {
      putJson = await r.json();
    } catch {
      putJson = null;
    }
  } catch {
    putRes = null;
  }

  if (!putRes || putRes.status === 504 || !putRes.ok) {
    let observed = null;
    try {
      const diag = await getStoredProject(id);
      if (diag.kind === 'ok') observed = { id: diag.project.id, name: diag.project.name, sector: diag.project.sector, country: diag.project.country, stage: diag.project.stage, key_dates: diag.project.key_dates };
    } catch {}
    return uncertain(res, observed);
  }

  const saved = parseStoredProject(putJson);
  if (!saved) {
    let observed = null;
    try {
      const diag = await getStoredProject(id);
      if (diag.kind === 'ok') observed = { id: diag.project.id, name: diag.project.name, sector: diag.project.sector, country: diag.project.country, stage: diag.project.stage, key_dates: diag.project.key_dates };
    } catch {}
    return uncertain(res, observed);
  }
  send(res, 200, { project: { id: saved.id, name: saved.name, sector: saved.sector, country: saved.country, stage: saved.stage, key_dates: saved.key_dates } });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://127.0.0.1');
  const path = url.pathname;
  if (req.method === 'GET' && path === '/api/projects') return listHandler(res);
  const m = path.match(/^\/api\/projects\/([^/]+)$/);
  if (m && req.method === 'GET') return showHandler(res, decodeURIComponent(m[1]));
  if (m && req.method === 'PUT') return saveHandler(req, res, decodeURIComponent(m[1]));
  send(res, 404, { code: 'project_not_found' });
});

server.listen(PORT, '0.0.0.0');

// @ts-nocheck
const http = require('node:http');

const PORT = Number(process.env.PORT || 8080);
const UPSTREAM_URL = process.env.UPSTREAM_URL;
const UPSTREAM_API_KEY = process.env.UPSTREAM_API_KEY;

function sendJson(res, status, body) {
  const data = Buffer.from(JSON.stringify(body));
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': data.length,
    'Cache-Control': 'no-store',
  });
  res.end(data);
}

function notFound(res) {
  sendJson(res, 404, { code: 'project_not_found' });
}

function upstreamUnavailable(res) {
  sendJson(res, 502, { code: 'upstream_unavailable' });
}

function uncertain(res, observed) {
  sendJson(res, 504, { code: 'write_uncertain', observed });
}

function badRequest(res, status = 422) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify({ detail: 'Validation error' }));
}

function isNonBlankString(v) {
  return typeof v === 'string' && v.trim().length > 0;
}

function isIsoDate(s) {
  if (typeof s !== 'string') return false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return false;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d;
}

function validateKeyDates(arr) {
  if (!Array.isArray(arr)) return false;
  for (const item of arr) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) return false;
    const keys = Object.keys(item);
    if (keys.length !== 2 || !('label' in item) || !('date' in item)) return false;
    if (!isNonBlankString(item.label) || !isIsoDate(item.date)) return false;
  }
  return true;
}

function validateEditable(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  const keys = Object.keys(obj);
  const allowed = new Set(['name', 'sector', 'country', 'stage', 'key_dates']);
  if (keys.length !== 5 || keys.some((k) => !allowed.has(k))) return false;
  const sectors = new Set(['energy', 'mining', 'water', 'transport', 'oil_and_gas', 'ict']);
  const stages = new Set(['idea', 'feasibility', 'tender', 'financing', 'construction', 'operation', 'cancelled']);
  return isNonBlankString(obj.name) && sectors.has(obj.sector) && isNonBlankString(obj.country) && stages.has(obj.stage) && validateKeyDates(obj.key_dates);
}

function validateSave(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return false;
  const keys = Object.keys(body);
  if (keys.length !== 2 || !('base' in body) || !('proposed' in body)) return false;
  return validateEditable(body.base) && validateEditable(body.proposed);
}

function summarize(p) {
  return { id: p.id, name: p.name, sector: p.sector, country: p.country, stage: p.stage };
}

function detail(p) {
  return { id: p.id, name: p.name, sector: p.sector, country: p.country, stage: p.stage, key_dates: p.key_dates };
}

function mergeEdit(base, proposed, current) {
  const fields = ['name', 'sector', 'country', 'stage', 'key_dates'];
  const merged = {};
  const conflicts = [];
  for (const f of fields) {
    if (JSON.stringify(proposed[f]) === JSON.stringify(base[f])) merged[f] = current[f];
    else if (JSON.stringify(current[f]) !== JSON.stringify(base[f]) && JSON.stringify(current[f]) !== JSON.stringify(proposed[f])) {
      merged[f] = current[f];
      conflicts.push(f);
    } else merged[f] = proposed[f];
  }
  const changed = JSON.stringify(merged) !== JSON.stringify({
    name: current.name,
    sector: current.sector,
    country: current.country,
    stage: current.stage,
    key_dates: current.key_dates,
  });
  return { merged, conflicts, changed };
}

async function upstreamFetch(path, options = {}) {
  if (!UPSTREAM_URL) throw new Error('missing upstream url');
  const url = new URL(path, UPSTREAM_URL);
  const headers = Object.assign({}, options.headers || {});
  if (UPSTREAM_API_KEY) headers['X-Api-Key'] = UPSTREAM_API_KEY;
  if (!headers['Content-Type'] && options.body) headers['Content-Type'] = 'application/json';
  const resp = await fetch(url, { ...options, headers });
  return resp;
}

async function readUpstreamJson(resp) {
  try {
    return await resp.json();
  } catch {
    return null;
  }
}

async function getCurrent(projectId) {
  try {
    const resp = await upstreamFetch(`/projects/${encodeURIComponent(projectId)}`);
    if (resp.status === 404) return { kind: 'missing' };
    if (!resp.ok) return { kind: 'unavailable' };
    const json = await readUpstreamJson(resp);
    if (!json || typeof json !== 'object') return { kind: 'unavailable' };
    return { kind: 'ok', project: json };
  } catch {
    return { kind: 'unavailable' };
  }
}

async function listProjectsHandler(res) {
  try {
    const resp = await upstreamFetch('/projects');
    if (!resp.ok) return upstreamUnavailable(res);
    const json = await readUpstreamJson(resp);
    if (!Array.isArray(json)) return upstreamUnavailable(res);
    sendJson(res, 200, { projects: json.map(summarize) });
  } catch {
    upstreamUnavailable(res);
  }
}

async function showProjectHandler(res, projectId) {
  const current = await getCurrent(projectId);
  if (current.kind === 'missing') return notFound(res);
  if (current.kind !== 'ok') return upstreamUnavailable(res);
  sendJson(res, 200, { project: detail(current.project) });
}

async function saveProjectHandler(res, projectId, body) {
  if (!validateSave(body)) return badRequest(res, 422);
  const base = body.base;
  const proposed = body.proposed;

  const fresh = await getCurrent(projectId);
  if (fresh.kind === 'missing') return notFound(res);
  if (fresh.kind !== 'ok') return upstreamUnavailable(res);

  const current = fresh.project;
  const result = mergeEdit(base, proposed, current);
  if (result.conflicts.length) {
    return sendJson(res, 409, { code: 'edit_conflict', current: detail(current), conflicting_fields: result.conflicts });
  }
  if (!result.changed) {
    return sendJson(res, 200, { project: detail(current) });
  }

  const putBody = {
    name: result.merged.name,
    sector: result.merged.sector,
    country: result.merged.country,
    stage: result.merged.stage,
    key_dates: result.merged.key_dates,
    linked_companies: current.linked_companies || [],
  };

  try {
    const resp = await upstreamFetch(`/projects/${encodeURIComponent(projectId)}`, {
      method: 'PUT',
      body: JSON.stringify(putBody),
    });
    if (resp.status === 404) return notFound(res);
    if (!resp.ok) {
      const observed = await getCurrent(projectId);
      return uncertain(res, observed.kind === 'ok' ? detail(observed.project) : null);
    }
    const json = await readUpstreamJson(resp);
    if (!json || typeof json !== 'object') {
      const observed = await getCurrent(projectId);
      return uncertain(res, observed.kind === 'ok' ? detail(observed.project) : null);
    }
    sendJson(res, 200, { project: detail(json) });
  } catch {
    const observed = await getCurrent(projectId);
    return uncertain(res, observed.kind === 'ok' ? detail(observed.project) : null);
  }
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => {
      data += chunk;
      if (data.length > 1e7) {
        reject(new Error('too large'));
        req.destroy();
      }
    });
    req.on('end', () => {
      if (!data) return resolve(null);
      try {
        resolve(JSON.parse(data));
      } catch {
        reject(new Error('bad json'));
      }
    });
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  const method = req.method || 'GET';
  const url = new URL(req.url || '/', 'http://localhost');

  if (method === 'GET' && url.pathname === '/api/projects') {
    return listProjectsHandler(res);
  }

  const match = /^\/api\/projects\/([^/]+)$/.exec(url.pathname);
  if (!match) {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    return res.end('Not Found');
  }

  const projectId = decodeURIComponent(match[1]);

  if (method === 'GET') return showProjectHandler(res, projectId);
  if (method === 'PUT') {
    try {
      const body = await parseBody(req);
      return saveProjectHandler(res, projectId, body);
    } catch {
      return badRequest(res, 422);
    }
  }

  res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Method Not Allowed');
});

server.listen(PORT, '0.0.0.0');
